import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './JsonFormatter.css';

const JsonFormatter = () => {
  const [leftText, setLeftText] = useState('');
  const [rightText, setRightText] = useState('');
  const [error, setError] = useState('');
  const [indentSize, setIndentSize] = useState(2);

  const formatLeftToRight = () => {
    try {
      const parsed = JSON.parse(leftText);
      const formatted = JSON.stringify(parsed, null, indentSize);
      setRightText(formatted);
      setError('');
    } catch (e) {
      setError('Invalid JSON in left panel: ' + e.message);
    }
  };

  const minifyLeftToRight = () => {
    try {
      const parsed = JSON.parse(leftText);
      const minified = JSON.stringify(parsed);
      setRightText(minified);
      setError('');
    } catch (e) {
      setError('Invalid JSON in left panel: ' + e.message);
    }
  };

  const formatRightToLeft = () => {
    try {
      const parsed = JSON.parse(rightText);
      const formatted = JSON.stringify(parsed, null, indentSize);
      setLeftText(formatted);
      setError('');
    } catch (e) {
      setError('Invalid JSON in right panel: ' + e.message);
    }
  };

  const minifyRightToLeft = () => {
    try {
      const parsed = JSON.parse(rightText);
      const minified = JSON.stringify(parsed);
      setLeftText(minified);
      setError('');
    } catch (e) {
      setError('Invalid JSON in right panel: ' + e.message);
    }
  };

  const clearAll = () => {
    setLeftText('');
    setRightText('');
    setError('');
  };

  const swapSides = () => {
    const temp = leftText;
    setLeftText(rightText);
    setRightText(temp);
  };

  return (
    <div className="json-formatter-page">
      <div className="json-header">
        <Link to="/" className="back-button">← Back to Home</Link>
        <h1>JSON Formatter</h1>
        <p>Format, minify, and validate JSON data</p>
      </div>

      <div className="json-container">
        {error && (
          <div className="error-section">
            <div className="error-message">❌ {error}</div>
          </div>
        )}

        <div className="controls-section">
          <div className="indent-control">
            <label>Indent Size:</label>
            <select value={indentSize} onChange={(e) => setIndentSize(Number(e.target.value))}>
              <option value={2}>2 spaces</option>
              <option value={4}>4 spaces</option>
              <option value={8}>8 spaces</option>
            </select>
          </div>
          <button onClick={swapSides} className="swap-button">
            ⇄ Swap Sides
          </button>
        </div>

        <div className="text-container">
          <div className="text-box">
            <h3>Left Panel</h3>
            <textarea
              value={leftText}
              onChange={(e) => setLeftText(e.target.value)}
              placeholder='{"name":"John","age":30}'
              className="json-textarea"
            />
          </div>
          <div className="text-box">
            <h3>Right Panel</h3>
            <textarea
              value={rightText}
              onChange={(e) => setRightText(e.target.value)}
              placeholder='Result will appear here...'
              className="json-textarea"
            />
          </div>
        </div>

        <div className="button-section">
          <div className="button-group">
            <h4>Left → Right</h4>
            <div className="button-row">
              <button onClick={formatLeftToRight} className="format-button">
                Format →
              </button>
              <button onClick={minifyLeftToRight} className="minify-button">
                Minify →
              </button>
            </div>
          </div>

          <div className="button-group">
            <h4>Right → Left</h4>
            <div className="button-row">
              <button onClick={formatRightToLeft} className="format-button">
                ← Format
              </button>
              <button onClick={minifyRightToLeft} className="minify-button">
                ← Minify
              </button>
            </div>
          </div>

          <button onClick={clearAll} className="clear-button">
            Clear All
          </button>
        </div>
      </div>
    </div>
  );
};

export default JsonFormatter;
